"""Prompt model."""

from dataclasses import dataclass

from sqlalchemy import ForeignKey, String, Text, UniqueConstraint
from sqlalchemy.orm import Mapped, mapped_column

from bot.db.base import Base, BigIntPK, TimestampMixin


class Prompt(TimestampMixin, Base):
    """User-defined prompt templates."""

    __tablename__ = "prompts"
    __table_args__ = (UniqueConstraint("user_id", "name", name="uq_prompts_user_name"),)

    # Internal surrogate primary key, generated by the database.
    id: Mapped[int] = mapped_column(BigIntPK, primary_key=True, autoincrement=True)

    name: Mapped[str] = mapped_column(String(128))
    text: Mapped[str] = mapped_column(Text)
    user_id: Mapped[int] = mapped_column(ForeignKey("users.id", ondelete="CASCADE"))

    def __repr__(self) -> str:
        return f"Prompt(id={self.id}, name={self.name!r})"


@dataclass(frozen=True, kw_only=True, slots=True)
class PromptCreateData:
    user_id: int
    name: str
    text: str
